Here's a simple example to illustrate inheritance in C++:

```cpp
#include <iostream>

// Base class
class Animal {
public:
    // Constructor
    Animal(const std::string& name) : name(name) {}

    // Virtual function
    virtual void speak() const {
        std::cout << name << " says: " << "An animal sound" << std::endl;
    }

    // Virtual destructor
    virtual ~Animal() {
        std::cout << name << " is destroyed" << std::endl;
    }

protected:
    std::string name;
};

// Derived class inheriting from Animal
class Dog : public Animal {
public:
    // Constructor
    Dog(const std::string& name, const std::string& breed) : Animal(name), breed(breed) {}

    // Overriding the speak function
    void speak() const override {
        std::cout << name << " says: Woof!" << std::endl;
    }

    // Additional method specific to Dog
    void wagTail() const {
        std::cout << name << " wags its tail" << std::endl;
    }

private:
    std::string breed;
};

int main() {
    // Creating an instance of Animal
    Animal* myAnimal = new Animal("Generic Animal");
    myAnimal->speak();  // Output: Generic Animal says: An animal sound
    delete myAnimal;

    // Creating an instance of Dog
    Dog* myDog = new Dog("Buddy", "Golden Retriever");
    myDog->speak();    // Output: Buddy says: Woof!
    myDog->wagTail();  // Output: Buddy wags its tail
    delete myDog;

    return 0;
}
```

### Explanation:

1. **Base Class (`Animal`)**:
   - **Attributes**: The `Animal` class has a protected attribute `name` that stores the name of the animal.
   - **Constructor**: The constructor initializes the `name` attribute.
